    tell(host, { answer: first ? reached + (worst ? " The biggest drop is from " + esc(low(SG[worst - 1].label)) + " to " + esc(low(SG[worst].label)) + ", where <b>" + share(SG[worst].value, SG[worst - 1].value) + "</b> moved on." : "") : "No " + esc(noun[1]) + " yet. They appear here as soon as the first ones are found.",
      key: [[SG[0].label, fmtN(first)]].concat(worst ? [[SG[worst - 1].label + " → " + SG[worst].label, share(SG[worst].value, SG[worst - 1].value), "warn"]] : []).concat([[SG[n - 1].label, fmtN(last), last ? "ok" : ""]]),
      legend: [[LG.dot("#5d3fe0"), "moved on to the next stage"], [LG.dot("rgba(255,255,255,.35)"), "stopped at this stage"], [LG.dot("#8b74f5"), "reached " + low(SG[n - 1].label)], [LG.bar(pMix(0.5)), "the share that moved on"]] });
