      const keyOf = (x) => (by === "none" ? ["all", "All"] : by === "label" ? [lxvLabels(x.it)[0] || "No label", lxvLabels(x.it)[0] || "No label"] : by === "who" ? [lxvWho(x.it) || "Nobody yet", lxvWho(x.it) || "Nobody yet"]
        : [lxvWhen(x.it), (LXV_WHEN.find(([k]) => k === lxvWhen(x.it)) || [, "No date"])[1].replace("Last 7 days", "This week").replace("Last 30 days", "This month")]);
