    const save = (fn) => { const nv = lxvGet(spec.id); fn(nv); lxvSet(spec.id, nv); redraw(); };
    const multi = (key, label, m, fixed) => { const opts = fixed ? fixed.filter(([k]) => m.has(k)).map(([k, l]) => [k, l, m.get(k)]) : [...m.entries()].sort((a, z) => z[1] - a[1]).slice(0, 12).map(([k, n]) => [k, k, n]);
      return opts.length > 1 || v.f[key].length ? { kit: true, label, multi: true, values: v.f[key], options: opts, pick: (val, on, clear) => save((nv) => { if (clear) nv.f[key] = []; else { const s2 = new Set(nv.f[key]); on ? s2.add(String(val)) : s2.delete(String(val)); nv.f[key] = [...s2]; } }) } : null; };
    const gm = count((x) => String(x.g.key)), gl = new Map(groups.map((g) => [String(g.key), g.label]));
    const labM = new Map(); all.forEach((x) => lxvLabels(x.it).forEach((l) => labM.set(l, (labM.get(l) || 0) + 1)));
    const grpSec = multi("grp", spec.groupWord || "Status", gm); if (grpSec) grpSec.options = [...gm.entries()].map(([k, n]) => [k, gl.get(k) || k, n]);
    const fil = [
      all.length > 7 || v.f.q ? { kit: true, search: true, label: "Words in the row", value: v.f.q, placeholder: "Type to filter " + String(spec.label || "rows").toLowerCase(), pick: (val) => save((nv) => { nv.f.q = String(val || "").slice(0, 80); }) } : null,
      grpSec, multi("lab", "Label", labM),
      all.some((x) => x.it.who !== undefined) ? multi("who", "Person", count((x) => (x.it.who === undefined ? "" : lxvWho(x.it) || "—"))) : null,
      all.some((x) => x.it.at) ? multi("when", "Date", (() => { const m = count((x) => lxvWhen(x.it)), t = m.get("today") || 0, w7 = t + (m.get("7") || 0);
        // "Last 7 days" includes today and "Last 30 days" the week, so the counts say what each choice shows
        if (m.has("7") || t) m.set("7", w7); if (m.has("30") || w7) m.set("30", w7 + (m.get("30") || 0)); return m; })(), LXV_WHEN) : null,
    ].filter((s) => s && (s.options || s.search) && (s.search || s.options.length));
