      '<span class="lx-labels">' + lxRowLabels(it) + '</span><span class="lx-meta">' + (it.meta || "") + "</span>" +
      (it.who !== undefined ? avatar(it.who) : '<span class="lx-av-gap"></span>') + timeTag(it.at) + "</li>";
