      if (b && b.dataset.lx === "csv") { csvDownload(spec.label || spec.id, lxCsvHead(groups), lxCsvRows(groups)); return; }
      if (b && (b.dataset.lx === "chip-x" || b.dataset.lx === "chip-all")) { lxvChipAct(b); return; }
      const row = e.target.closest(".lx-row"); if (!row) return;
