      if (e.shiftKey) { const rs = rows(), a = rs.indexOf(ctl.current()), z = rs.indexOf(row); if (a >= 0) { rs.slice(Math.min(a, z), Math.max(a, z) + 1).forEach((r) => { if (!mem.sel.includes(r.dataset.id)) { mem.sel.push(r.dataset.id); r.setAttribute("aria-selected", "true"); } }); ctl.bulkDraw(); } ctl.focus(row); return; }
