    if (spec && typeof spec.then === "function") { pk.o.el.innerHTML = peekHtml({ ref: item.ref, title: item.title, glyph: item.glyph, body: '<div class="xp-skel" style="height:120px"></div>' }, nav); try { spec = await spec; } catch (e) { logFault("panel " + item.ref, e); spec = { ref: item.ref, title: item.title, body: '<p class="xp-err">' + esc(actionErrText(e)) + "</p>" }; } }
    if (token !== pk.token || !pk.o.el.isConnected) return;
    const keep = pk.o.el.querySelector(".lx-pk-body"), top = keep ? keep.scrollTop : 0, same = pk.shownId === pk.id;
    spec = spec ? { ...spec, rowLabels: spec.rowLabels ?? lxPanelLabels(item) } : spec;
    pk.o.el.innerHTML = peekHtml(spDecorate(spec || {}), nav); pk.shownId = pk.id; pk.spec = spec || {};
    pk.close = () => peekClose(); pk.refresh = (next) => (next && typeof next === "object" ? (pk.o.el.innerHTML = peekHtml(spDecorate((pk.spec = next)), nav)) : peekShow(pk.listCtl || list, ((pk.listCtl || list).byId || {})[pk.id] || item));
    const body = pk.o.el.querySelector(".lx-pk-body"); if (body && same) body.scrollTop = top;
    if (!pk.o.el.contains(document.activeElement)) pk.o.el.focus({ preventScroll: true });
