  // }
  // Colour is never the only signal (WCAG 1.4.1): every fact has its words, and its full meaning as a tooltip.
  const FACT_KEYS = ["status", "owner", "due", "age", "value", "difficulty", "effort", "saves", "health", "risk", "score", "source"];
  const DIFF = { easy: 1, low: 1, medium: 2, med: 2, hard: 3, high: 3 };
  const DIFF_WORD = ["", "Easy", "Medium", "Hard"];
  const daysFrom = (iso) => { const d = dateOf(iso); if (!d) return null; const a = new Date(d.getFullYear(), d.getMonth(), d.getDate()), n = new Date(); const b = new Date(n.getFullYear(), n.getMonth(), n.getDate()); return Math.round((a - b) / 864e5); };
  const hrs = (h) => { const n = num(h); return n >= 10 ? Math.round(n) + "h" : n >= 1 ? (Math.round(n * 2) / 2) + "h" : Math.max(5, Math.round(n * 60 / 5) * 5) + "m"; };
