    if (k === "status") { const [t, tone] = Array.isArray(v) ? v : [v, ""]; return t ? { k, text: String(t), tone: tone || "", title: "Status: " + t } : null; }
    if (k === "owner") { const n = /^(xevrion|system)$/i.test(String(v)) ? "Xevrion" : String(v); return { k, text: n, tone: "", title: "Owner: " + n, who: n }; }
    if (k === "due") { const d = daysFrom(v); if (d === null) return null; const t = d < 0 ? -d + "d late" : d === 0 ? "Due today" : d === 1 ? "Due tomorrow" : d < 7 ? "Due in " + d + "d" : "Due " + dateOf(v).toLocaleDateString("en-GB", { day: "numeric", month: "short" });
      return { k, text: t, tone: d < 0 ? "red" : d <= 1 ? "amber" : "", title: "Due " + when(v), ic: "calendar" }; }
    if (k === "age") { const d = daysFrom(v); if (d === null) return null; const n = Math.max(0, -d), warn = num(f.ageWarn || 2);
      return { k, text: n === 0 ? "New today" : "Waiting " + n + "d", tone: n > warn * 3 ? "red" : n > warn ? "amber" : "", title: "Waiting since " + when(v), ic: "clock" }; }
    // whole pounds unless the amount has pence (a row reads "£720", not "£720.00")
    if (k === "value") { const n = num(v), t = Number.isInteger(n) ? "£" + fmtN(n) : money(n); return { k, text: t, tone: "", title: "Worth " + t, num: true }; }
    if (k === "difficulty") { const lv = typeof v === "number" ? Math.max(1, Math.min(3, Math.round(v))) : DIFF[String(v).toLowerCase()] || 0; if (!lv) return null;
      return { k, text: DIFF_WORD[lv], tone: lv === 3 ? "amber" : "", title: "Difficulty: " + DIFF_WORD[lv], level: lv }; }
    if (k === "effort") { const n = num(v); return n > 0 ? { k, text: "~" + hrs(n), tone: "", title: "About " + hrs(n) + " of work", ic: "clock" } : null; }
    if (k === "saves") { const n = num(v); return n > 0 ? { k, text: "Saves " + hrs(n) + "/wk", tone: "green", title: "Saves about " + hrs(n) + " a week", ic: "clock" } : null; }
