      head.insertAdjacentHTML("beforeend", '<span class="xq-more">' + (urgent ? chip("Needs you", "warn") : "") + '<span class="xq-chev">' + icon("arrow", 14) + "</span></span>");
      li.dataset.open = open ? "1" : "";
      const toggle = () => { const o = li.dataset.open !== "1"; li.dataset.open = o ? "1" : ""; head.setAttribute("aria-expanded", String(o)); if (o) { const t = body.querySelector("textarea"); if (t) setTimeout(() => t.focus({ preventScroll: true }), 50); } };
      head.addEventListener("click", (e) => { if (e.target.closest("button,a,summary")) return; toggle(); });
