    const cards = [...page.querySelectorAll(":scope > .xp-card, :scope > .xp-g > .xp-card, :scope > .xc-grid .xp-card")].filter((c) => !c.hidden && c.offsetParent !== null && c.querySelector(".xp-card-h h3"));
    if (cards.length < 4) return;
