    stopViz(); closePop(); if (S.setupDrawer) { S.setupDrawer.close(); S.setupDrawer = null; } const top = main.scrollTop;
    navProgress(true);
    // The bar (breadcrumb and h1) is drawn at once; a new page's body is a skeleton until its data arrives (NN/g: a
