      if (p.id === "security") { const d = await settle(api(O("/dashboard"))); if (d.ok) { S.dash = d.v; S.dashCache = { org: S.org, t: Date.now() }; } else if (d.e && d.e.status === 403) S.policyBlock = d.e.message; else throw d.e; }
