      if (/^select:/.test(f.type)) return field({ name: f.key, label: f.label, type: "select", options: f.type.slice(7).split("/").map((o) => { const [k, l] = o.split("="); return [k, l || cap(k)]; }), value: preset[f.key] || "" });
