    const workspace_ = [["connections", "Connect a tool", "Your inbox, CRM, accounts and more"], ["team", "Invite a teammate", "Choose what each person can do"], ["setup", "Review setup", "The eight setup steps"], ["billing", "See your plan and invoices", ""],
      ["value", "See the value in pounds", "Every result, with its proof"], ["security", "Turn on two-factor sign-in", ""], ["data", "Export your data", ""], ["support", "Ask the Xevrion team a question", "Answered in writing"]]
