    const H = health.ok ? health.v : null, I = integ.ok ? integ.v.items || [] : [], V = value.ok ? value.v : null, SUP = support.ok ? support.v.items || [] : [], A = ai.ok ? ai.v : null, N = notes.ok ? notes.v.items || [] : [];
