      const closer = (id) => ops.find((r) => ["resolve", "confirm"].includes(r.action) && r.status === "completed" && JSON.stringify(r).includes(String(id)));
      return responseRace(host, { targetHours: 24,
        items: ops.filter((r) => r.action === "support_intake" && r.status === "completed" && rc(r).id).map((r) => { const f = closer(rc(r).id);
          return { who: cust(r) || "Customer", label: rc(r).message || "Support request", sub: "Case " + rc(r).id, start: r.completed_at, end: f ? f.completed_at : null, health: health[cust(r)], action: f ? "confirm" : "resolve" }; }),
        onPick: (x) => pick(x.action || "support_intake") });
