    if (open && can && !d.opened_at && !S.demo) { S.careOpened = S.careOpened || {}; if (!S.careOpened[d.id]) { S.careOpened[d.id] = 1; post(O("/care/drafts/" + encodeURIComponent(d.id) + "/opened")).catch(() => { delete S.careOpened[d.id]; }); } }
    // a first message to a new customer (a sales enquiry from someone not yet a customer) needs one tick before it goes
