    "care-send": async (b) => { const id = b.dataset.id, text = String(val("care_" + id) || "").trim(); if (text.length < 2) throw Error("Write a reply first, or skip it.");
      // sending again after an unconfirmed send is rare and could reach the customer twice: that keeps its question, and goes at once
      if (b.dataset.again) { if (!(await ask({ title: "Send this reply again?", text: "The last send was not confirmed. Check your Sent folder first, so the customer does not get it twice.", confirm: "Send again" }))) return;
        await post(O("/care/drafts/" + encodeURIComponent(id) + "/send"), { text, confirm_resend: true }); toast("Sent from your inbox.", "ok"); reload(); return; }
      careSendLater(id, text); },
    "care-skip": async (b) => { await post(O("/care/drafts/" + encodeURIComponent(b.dataset.id) + "/skip")); toast("Skipped. Nothing was sent.", "ok"); reload(); },
