    "cust-checkin": async (b) => { const id = b.dataset.id, d = await api(O("/customers/" + encodeURIComponent(id) + "/check-in"));
      drawer({ title: "Check in", sub: "To " + d.to + ", from your own inbox. Edit it first if you like.", body: field({ name: "subject", label: "Subject", value: d.subject }) + field({ name: "text", label: "Message", type: "textarea", rows: 9, value: d.text }), submitLabel: "Send",
        submit: async (v) => { await post(O("/customers/" + encodeURIComponent(id) + "/check-in"), { subject: String(v.subject || "").trim(), text: String(v.text || "").trim() }); toast("Sent from your inbox.", "ok"); reload(); } }); },
    "imp-apply": async (b) => { const r = ((S.imp && S.imp.open) || []).find((x) => x.id === b.dataset.id); if (!r) throw Error("Refresh the page: this improvement changed.");
      let body = {};
      if (r.needs) { const v = await ask({ title: r.title, text: r.change, confirm: "Apply", fields: field({ name: "value", label: "Hourly cost (£)", hint: "the cost of an hour of the people who do this work, for example 25", type: "number" }) }); if (!v) return; body = { value: Number(v.value) }; }
      else if (r.kind === "setting" && !(await ask({ title: r.title + "?", text: r.change + " You can turn it off again in its settings, or undo it here.", confirm: "Apply" }))) return;
      await post(O("/improvements/" + encodeURIComponent(r.id) + "/apply"), body); toast(r.safe ? "Switched on. Drafts will appear for you to check." : "Applied.", "ok"); reload(); },
    "imp-undo": async (b) => { if (!(await ask({ title: "Undo this improvement?", text: "The settings go back to how they were, and it will not be applied by itself again.", confirm: "Undo" }))) return;
      await post(O("/improvements/" + encodeURIComponent(b.dataset.id) + "/undo")); toast("Undone.", "ok"); reload(); },
    "imp-dismiss": async (b) => { await post(O("/improvements/" + encodeURIComponent(b.dataset.id) + "/dismiss")); toast("Set aside for 30 days.", "ok"); reload(); },
