    "close-status": async () => { const id = String(val("closure_id")).trim(); if (!id) throw Error("Enter the offboarding request ID"); const r = await api(O("/offboarding/" + encodeURIComponent(id))); $("xpClosure").innerHTML = '<div style="margin-top:14px">' + statsRow([["Status", status(r.status)], ["Requested", esc(when(r.requested_at))]]) + '<div class="xp-flow" style="margin-top:12px">' + (r.steps || []).map((s, i) => (i ? '<span class="xp-flow-a"></span>' : "") + '<div class="xp-flow-n"><b>' + esc(cap(s)) + "</b></div>").join("") + "</div>" + evidence(r) + "</div>"; },
