    S.root.innerHTML = '<div class="xp" data-screen="auth"><div class="xp-auth">' +
      authStage("Xevrion Ops · 14 days free", "More time back. Fewer things missed.", "Six AI agents answer client email, plan the work, invoice and chase. You approve what matters.") +
      '<section class="xp-auth-panel"><div class="xp-auth-card"><a class="xp-auth-brand" href="#" aria-label="Xevrion Ops">' + MARK + "<b>XEVRION</b><span>OPS</span></a>" +
      '<div class="xp-tabs" role="tablist" aria-label="Sign in or start a free trial">' + [["signin", "Sign in"], ["create", "Start free trial"]].map(([k, l]) => '<button type="button" role="tab" data-act="auth-tab" data-tab="' + k + '" aria-selected="' + (k === tab) + '">' + l + "</button>").join("") + "</div>" +
      '<div id="xpAuthBody" class="xp-form"></div><p class="xp-err" id="xpAuthErr" role="alert">' + esc(message) + "</p>" + authNote + '<div class="xp-toasts" id="xpToasts" aria-live="polite"></div></div></section></div></div>';
