      '<div class="xp-auth-step">' + field({ name: "reset", label: "Password reset code" }) + field({ name: "password", label: "New password", hint: "at least 12 characters", type: "password", attrs: ' autocomplete="new-password"' }) + btn("Set the new password", "reset-finish") + "</div>" + '<div class="xp-auth-row">' + back + "</div>";
    setTimeout(() => { const f = b.querySelector("input"); if (f) f.focus(); }, 30);
