    "@media (hover:none){.xp .xa-mt{opacity:1}}",
    // an answer: the mark, then the words; no box around them, so the answer reads as a reply
    ".xp .xa-m{display:grid;grid-template-columns:24px minmax(0,1fr);gap:12px;align-items:start;min-width:0}.xp .xa-av{display:grid;place-items:center;width:24px;height:24px;margin-top:2px}",
