    ".xp .xa-tag svg{flex:none}.xp .xa-tag[data-t=checked]{border-color:color-mix(in srgb,var(--tone-green-line,#8b74f5) 50%,var(--bg1,#101113));color:var(--tone-green-ink,#a796f8)}",
