    ".xp .xa-a{display:grid;gap:10px;min-width:0;color:var(--t2);font:400 14px/22px var(--font);overflow-wrap:break-word}.xp .xa-a p{margin:0}.xp .xa-a strong{color:var(--t1);font-weight:600}",
    ".xp .xa-a ul,.xp .xa-a ol{display:grid;gap:4px;margin:0;padding-left:20px}.xp .xa-a p+p,.xp .xa-a li+li{margin-top:0}.xp .xa-a h4{margin:4px 0 0;color:var(--t1);font:600 14px/20px var(--font)}",
