    ".xp .xa-a td{max-width:320px;padding:6px 12px;border-top:1px solid var(--line2);color:var(--t1);vertical-align:top;overflow-wrap:normal}.xp .xa-a tr:first-child td{border-top:0}",
    ".xp .xa-a th[data-n],.xp .xa-a td[data-n]{text-align:right;white-space:nowrap}",
