    ".xp .xa-per{display:flex;align-items:flex-start;gap:8px;margin:-4px 0 0;color:var(--t3);font:400 12px/16px var(--font)}.xp .xa-per svg{flex:none;margin-top:2px;color:var(--t3)}.xp .xa-per em{font-style:normal}",
    ".xp .xa-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:0;margin:0;border:1px solid var(--line2);border-radius:var(--r-card,10px);overflow:hidden}",
    ".xp .xa-kpis>div{display:grid;align-content:start;gap:4px;min-width:0;padding:12px;border-left:1px solid var(--line2)}.xp .xa-kpis>div:first-child{border-left:0}",
    ".xp .xa-kpis dt{color:var(--t3);font:500 12px/16px var(--font)}.xp .xa-kpis dd{margin:0;color:var(--t1);font:600 16px/20px var(--font);font-variant-numeric:tabular-nums;letter-spacing:-.01em;overflow-wrap:anywhere}",
    ".xp .xa-kpis dd.xa-ksub{color:var(--t3);font:400 12px/16px var(--font);letter-spacing:0}.xp .xa-kpis>div[data-t=green] dd.xa-ksub{color:var(--tone-green-ink,#a796f8)}.xp .xa-kpis>div[data-t=red] dd.xa-ksub{color:var(--tone-red-ink,#ddd7fd)}",
    ".xp .xa-chart{display:grid;gap:8px;min-width:0;padding:12px 12px 8px;border:1px solid var(--line2);border-radius:var(--r-card,10px)}.xp .xa-chart .xa-cht{margin:0;color:var(--t2);font:500 12px/16px var(--font)}",
    ".xp .xa-chart figure.ch{margin:0}",
    ".xp .xa-rows{margin:0;padding:0;list-style:none;border:1px solid var(--line2);border-radius:var(--r-card,10px);overflow:hidden}.xp .xa-rows li+li{border-top:1px solid var(--line2)}",
    ".xp .xa-row{display:grid;grid-template-columns:8px minmax(0,1fr) auto;gap:12px;align-items:center;width:100%;min-height:48px;padding:8px 12px;border:0;background:transparent;color:inherit;font:inherit;text-align:left}",
    ".xp button.xa-row{cursor:pointer}.xp button.xa-row:hover{background:rgba(255,255,255,.03)}.xp .xa-row:focus-visible{outline:2px solid var(--xp-purple,#5d3fe0);outline-offset:-2px}",
    ".xp .xa-row i{width:8px;height:8px;border-radius:50%;background:var(--tone-neutral-line,#3a3d44)}.xp .xa-row[data-t=red] i{background:var(--tone-red-line,#ddd7fd)}.xp .xa-row[data-t=amber] i{background:var(--tone-amber-line,#b9adfa)}",
