    ".xp .xa-row em{color:var(--t1);font:600 13px/20px var(--font);font-style:normal;font-variant-numeric:tabular-nums;white-space:nowrap}.xp .xa-row[data-t=red] em{color:var(--tone-red-ink,#ddd7fd)}.xp .xa-row[data-t=amber] em{color:var(--tone-amber-ink,#c9bdfb)}",
    ".xp .xa-steps-l .xa-row{grid-template-columns:24px minmax(0,1fr)}.xp .xa-steps-l .xa-row i{display:grid;place-items:center;width:24px;height:24px;border:1px solid var(--line2);background:transparent;color:var(--t1);font:600 12px/22px var(--font);font-style:normal}",
    ".xp .xa-steps-l .xa-row b{white-space:normal}",
    // what to do, what it rests on, and the message's own tools: one toolbar each, the same buttons
    ".xp .xa-acts{display:flex;flex-wrap:wrap;gap:8px}",
