    ".xp .xa-src li{display:grid;grid-template-columns:32px minmax(0,1fr) auto;gap:12px;align-items:center;padding:8px 12px;color:var(--t2);font:400 13px/20px var(--font)}.xp .xa-src li+li{border-top:1px solid var(--line2)}",
    ".xp .xa-ref{color:var(--t3);font:500 12px/16px var(--mono)}",
