      if (/^\s*>\s?/.test(l)) { const q = []; while (i < lines.length && /^\s*>\s?/.test(lines[i])) q.push(lines[i++].replace(/^\s*>\s?/, "")); html += "<blockquote>" + q.map(askInline).join("<br>") + "</blockquote>"; continue; }
      if (/^\s*[-•*]\s+/.test(l)) { const xs = []; while (i < lines.length && /^\s*[-•*]\s+/.test(lines[i])) xs.push(lines[i++].replace(/^\s*[-•*]\s+/, "")); html += "<ul>" + xs.map((x) => "<li>" + askInline(x) + "</li>").join("") + "</ul>"; continue; }
      if (/^\s*\d+[.)]\s+/.test(l)) { const xs = []; while (i < lines.length && /^\s*\d+[.)]\s+/.test(lines[i])) xs.push(lines[i++].replace(/^\s*\d+[.)]\s+/, "")); html += "<ol>" + xs.map((x) => "<li>" + askInline(x) + "</li>").join("") + "</ol>"; continue; }
