    const n = pts.length, mx = pts.reduce((a, p) => a + +p.x, 0) / (n || 1), my = pts.reduce((a, p) => a + +p.y, 0) / (n || 1);
    const den = pts.reduce((a, p) => a + (p.x - mx) ** 2, 0), b = den ? pts.reduce((a, p) => a + (p.x - mx) * (p.y - my), 0) / den : 0;
    const x0 = Math.min(...pts.map((p) => +p.x)), x1 = Math.max(...pts.map((p) => +p.x)), y0 = my + b * (x0 - mx), y1 = my + b * (x1 - mx);
    if (n >= 3 && den && y0 >= sy.lo && y1 >= sy.lo && y0 <= sy.hi && y1 <= sy.hi) g += '<path class="ch-target" d="M' + chFix(X(x0)) + " " + chFix(Y(y0)) + "L" + chFix(X(x1)) + " " + chFix(Y(y1)) + '"/>';
    let marks = "";
    pts.forEach((p, i) => {
      g += '<circle cx="' + chFix(X(+p.x)) + '" cy="' + chFix(Y(+p.y)) + '" r="4" fill="' + CH.x + '" stroke="' + CH.surface + '" stroke-width="2"/>';
      marks += chMarkEl("circle", 'cx="' + chFix(X(+p.x)) + '" cy="' + chFix(Y(+p.y)) + '" r="10" fill="transparent"', { h: p.label || "", r: [[s.x_name || "X", CH.x, ex(+p.x)], [s.y_name || "Y", CH.x, ey(+p.y)]], ay: Y(+p.y) - 4 }, i === 0);
    });
    return { svg: chSvg(W, H, s.label, g + marks), legend: "", table: { head: [s.rowName || "Each", s.x_name || "X", s.y_name || "Y"], rows: pts.map((p) => [p.label || "", ex(+p.x), ey(+p.y)]) } };
