    const att = (id, s, ch, oy) => { const x = (side[id] = side[id] || { L: [], R: [] }); x[s].push([ch, oy]); };
    chains.forEach((ch) => { const ids = ch.ids;
      if (ch.same) { att(ids[0], "R", ch, items[ids[1]].y); att(ids[1], "R", ch, items[ids[0]].y); return; }
      att(ids[0], "R", ch, items[ids[1]].y + items[ids[1]].h / 2); att(ids[ids.length - 1], "L", ch, items[ids[ids.length - 2]].y + items[ids[ids.length - 2]].h / 2); });
    const port = {};                                    // chain index:id:side -> y
    Object.entries(side).forEach(([id, s]) => { const it = items[id];
      ["L", "R"].forEach((k) => { const list = s[k].sort((p, q) => p[1] - q[1]), m = list.length, g = Math.min(9, (it.h - 14) / Math.max(1, m - 1));
        list.forEach(([ch], i) => { port[ch.ci + ":" + id + ":" + k] = Math.round(it.y + it.h / 2 + (m > 1 ? (i - (m - 1) / 2) * g : 0)) + 0.5; }); }); });
