    const hs = hot.map((r, i) => ({ id: "hot:" + r.id, ref: "RISK-" + (i + 1), icon: "shield", title: r.label, sub: r.sentence, labels: [["Risk " + r.risk + " of 100", r.risk >= 70 ? "red" : ""]], data: r }));
