    ".xp .aug-side-br code{color:var(--v200);font-size:11.5px}.xp .aug-side-br small,.xp .aug-side-l small{color:var(--t2);font-size:11.5px}.xp .aug-side-l li{display:flex;flex-wrap:wrap;align-items:baseline;gap:4px 8px}",
