    ".xp .aug-key svg{flex:none;width:16px;height:16px}.xp .aug-key .awf-ic{fill:#16171a;stroke:#2a2c31}.xp .aug-key [data-k=trigger] .awf-ic,.xp .aug-key [data-k=ai] .awf-ic,.xp .aug-key [data-k=approval] .awf-ic{fill:rgba(93,63,224,.18);stroke:#5d3fe0}",
    ".xp .aug-key [data-k=trigger] .awf-g,.xp .aug-key [data-k=ai] .awf-g,.xp .aug-key [data-k=approval] .awf-g{stroke:#a796f8}",
