    // 16C: the run timeline: each recent run on the 30-day axis, and the list under it with Replay on every run
    ".xp .au-rt{position:relative;height:44px;margin:4px 8px 6px}.xp .au-rt-ax{position:absolute;left:0;right:0;top:15px;border-top:1px solid #26282d}",
    ".xp .au-rt-tk{position:absolute;top:24px;transform:translateX(-50%);color:#80848e;font-size:10.5px;white-space:nowrap}.xp .au-rt-tk::before{content:'';position:absolute;left:50%;top:-14px;height:10px;border-left:1px solid #26282d}.xp .au-rt-tk[data-a=s]{transform:none}.xp .au-rt-tk[data-a=s]::before{left:0}.xp .au-rt-tk[data-a=e]{transform:translateX(-100%)}.xp .au-rt-tk[data-a=e]::before{left:auto;right:0}",
    ".xp .au-rt-m{position:absolute;top:9px;width:13px;height:13px;margin-left:-6.5px;padding:0;border:1.5px solid #8b74f5;border-radius:50%;background:#0b0c0e;cursor:pointer}.xp .au-rt-m[data-s=succeeded]{background:#5d3fe0;border-color:#5d3fe0}.xp .au-rt-m[data-s=waiting]{border-style:dashed}",
    ".xp .au-rt-m:hover,.xp .au-rt-m[data-on]{border-color:#f2f3f5}.xp .au-rt-m:focus-visible{outline:2px solid #8b74f5;outline-offset:2px}",
    ".xp .au-rl{margin:0;padding:0;list-style:none;border-top:1px solid var(--line)}.xp .au-rl li{display:grid;grid-template-columns:150px 92px minmax(0,1fr) 84px 72px auto;gap:12px;align-items:center;min-height:40px;padding:4px 2px;border-bottom:1px solid var(--line);font-size:12.5px}",
    ".xp .au-rl li[data-on]{background:rgba(93,63,224,.08)}.xp .au-rl .xp-mono{overflow:hidden;color:var(--t2);font-size:11.5px;text-overflow:ellipsis;white-space:nowrap}.xp .au-rl small{color:var(--t2)}.xp .au-rl .au-rd{color:var(--t2);font:500 11.5px var(--font);text-align:right}",
    "@media (max-width:760px){.xp .au-runs-figs{grid-template-columns:repeat(2,minmax(0,1fr))}.xp .au-rl li{grid-template-columns:minmax(0,1fr) auto;row-gap:2px;padding:8px 2px}.xp .au-rl li>:is(.xp-mono,.au-rd,time){display:none}",
    ".xp .au-rl li>.au-rs{grid-row:1;grid-column:1}.xp .au-rl li>:last-child{grid-row:1;grid-column:2}.xp .au-rl li>span:nth-child(3){grid-row:2;grid-column:1/-1;color:var(--t2);font-size:12px}.xp .au-rt-tk:not([data-a]){display:none}}",
    ".xp .au-rs{display:inline-flex;align-items:center}",
    ".xp .au-runs-e{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px 16px;margin:12px 0 0;padding:14px;border:1px dashed var(--line2);border-radius:8px;color:var(--t2);font-size:12.5px;line-height:1.5}",
    ".xp .au-fbar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 20px;padding:10px 20px;border-bottom:1px solid var(--line)}.xp .au-fg{display:flex;flex-wrap:wrap;align-items:center;gap:5px}",
    ".xp .au-fg>span{margin-right:3px;color:var(--t2);font-size:12px}",
    ".xp .au-fb{display:inline-flex;align-items:center;min-height:28px;padding:0 11px;border:1px solid var(--line2);border-radius:999px;background:transparent;color:var(--t1);font:520 12px var(--font);cursor:pointer}",
    ".xp .au-fb i{margin-left:6px;color:var(--t2);font:500 11px var(--font);font-style:normal}.xp .au-fb:hover{border-color:var(--line3);background:var(--bg2)}",
