    "@media (prefers-reduced-motion:reduce){.xp .aug-n-b{transition:none}}",
    // the workflow page header (13A item 1): title on the left, its actions on the right, figures under both
    ".xp .au-dstats small{display:block;margin-top:3px;color:var(--t2);font-size:11.5px;line-height:1.4;white-space:normal}",
    ".xp .au-dtop{display:flex;flex-wrap:wrap;align-items:flex-start;justify-content:space-between;gap:12px 24px;margin-bottom:16px}.xp .au-dtop .au-dh{flex:1;min-width:280px;margin:0}",
    ".xp .au-dtop .au-dh h2{font:600 18px/24px var(--font);letter-spacing:-.01em}.xp .au-dtop .au-dh p{max-width:720px}.xp .au-dtop .ws-actions{margin:0;justify-content:flex-end}.xp .au-dact{display:grid;justify-items:end;gap:6px;max-width:560px}.xp .au-dact .ws-note{margin:0;text-align:right}",
    ".xp .au-uses{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:12px 0 4px}.xp .au-uses>span{margin-right:4px;color:var(--t2);font-size:12px}.xp .au-uses .au-syss{margin:0}",
