    ".xp .auv-a{display:flex;align-items:center;gap:8px}.xp .auv-x{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border:1px solid var(--line2);border-radius:8px;background:transparent;color:var(--t1);cursor:pointer}",
    ".xp .auv-x:hover{background:var(--bg3)}.xp .auv-x:focus-visible{outline:2px solid var(--v400);outline-offset:2px}",
    ".xp .auv-b{display:grid;grid-template-columns:minmax(0,1fr) 380px;min-height:0}",
