    ".xp .auv-tabs button{display:inline-flex;align-items:center;gap:6px;min-height:32px;padding:0 12px;border:1px solid transparent;border-radius:7px;background:transparent;color:var(--t2);font:560 13px var(--font);cursor:pointer}",
