    ".xp .auv-tabs i{color:var(--t2);font:500 11px var(--font);font-style:normal}",
    ".xp .auv-pb{min-height:0;overflow:auto}.xp .auv-side{max-height:none;border-left:0;background:transparent}.xp .auv-about{padding:4px 16px 16px}.xp .auv-about .au-secs{grid-template-columns:1fr}",
    ".xp .auv-stages{display:grid;gap:12px;margin:0;padding:12px 12px 20px;list-style:none}",
    ".xp .auv-stages h5{display:flex;align-items:center;gap:8px;margin:0 0 6px;color:var(--t1);font:600 12.5px var(--font)}.xp .auv-stages h5 .xp-mono{color:var(--t2);font-size:11px}",
    ".xp .auv-stages h5 small{margin-left:auto;color:var(--t2);font:500 11.5px var(--font)}",
    ".xp .auv-steps{display:grid;gap:2px;margin:0;padding:0;list-style:none}",
