    ".xp .tm-compose-f{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.xp .tm-compose-f>span{flex:1;display:flex;flex-wrap:wrap;gap:4px;align-items:center;color:#80848e;font-size:12px}",
    ".xp .tm-chip{display:inline-flex;align-items:center;gap:4px;height:24px;padding:0 8px 0 4px;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:none;color:#c9ced6;font:500 12px var(--font);cursor:pointer}",
    ".xp .tm-chip:hover,.xp .tm-chip:focus-visible{border-color:rgba(255,255,255,.18);color:#f7f8f8;outline:none}.xp .tm-chip .lx-av{width:16px;height:16px;font-size:8px}",
    ".xp .tm-mini{list-style:none;margin:0;padding:0;display:grid;border:1px solid rgba(255,255,255,.07);border-radius:8px}",
    ".xp .tm-mini li+li{border-top:1px solid rgba(255,255,255,.05)}",
    ".xp .tm-mini button{display:grid;grid-template-columns:16px minmax(0,1fr) auto auto;gap:12px;align-items:center;width:100%;min-height:36px;padding:4px 12px;border:0;background:none;color:#c9ced6;font:inherit;text-align:left;cursor:pointer}",
    ".xp .tm-mini button:hover,.xp .tm-mini button:focus-visible{background:rgba(255,255,255,.03);outline:none}.xp .tm-mini b{font-weight:500;color:#f7f8f8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}",
    ".xp .tm-mini small{color:#80848e;font-size:12px;white-space:nowrap}",
    ".xp .tm-weeks{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:4px;align-items:end;height:44px}",
    ".xp .tm-weeks i{position:relative;display:block;min-height:2px;border-radius:3px 3px 1px 1px;background:#c9ced6}.xp .tm-weeks i[data-zero='1']{background:rgba(255,255,255,.07)}",
    ".xp .tm-weeks{height:64px;padding-top:16px;border-bottom:1px solid rgba(255,255,255,.12)}.xp .tm-weeks i span{position:absolute;left:-12px;right:-12px;bottom:100%;text-align:center;margin-bottom:2px;color:#c9ced6;font:500 10px var(--mono);font-variant-numeric:tabular-nums}",
    ".xp .tm-weeks-sum{margin:0 0 8px;color:#80848e;font-size:12px}.xp .tm-weeks-sum b{color:#f7f8f8;font-weight:560;font-variant-numeric:tabular-nums}",
    ".xp .tm-weeks-ax{display:flex;justify-content:space-between;margin-top:4px;color:#80848e;font:500 11px var(--mono)}",
    ".xp .tm-sr{position:absolute!important;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}",
    ".xp .tm-hidden-note{margin:12px 24px 0;padding:8px 12px;border:1px solid rgba(255,255,255,.07);border-radius:8px;color:#80848e;font-size:12px}",
