      if (S.page !== "team_work") return;
      tmRemember({ people: v.people, me: v.me }); S.tmLoad = Object.fromEntries((v.people || []).map((p) => [p.id, p])); S.tmCanAssignSrv = v.can_assign;
      const mine = (v.people || []).find((p) => p.id === v.me);
