    if (person) q.set("assignee", person); if (f.kind) q.set("kind", f.kind); if (f.priority) q.set("priority", f.priority); if (f.due) q.set("due", f.due);
    const r = await api(TB("/work?" + q.toString()));
    if (S.page !== "team_work") return;
    tmRemember(r); S.tmCanAssignSrv = r.can_assign;
    tmHead(tab, { people: (r.people || []).length, work: r.counts.todo + r.counts.in_progress, mine: r.counts.mine }, null, r);
