    const sec = (label, key, options) => ({ label, options, value: f[key] || "", base: "", pick: (val) => { S.tmF = { ...(S.tmF || {}), [key]: val }; reload(); } });
    const filter = list ? { sections: (tab === "work" ? [sec("Person", "person", [["", "Everyone"], ["me", "Me"], ["none", "Nobody yet"]].concat(people.map((p) => [p.id, p.name])))] : []).concat([
      sec("Type", "kind", [["", "Every type"]].concat(Object.entries(TM_KINDS).map(([k, x]) => [k, x[0]]))),
      sec("Priority", "priority", [["", "Any priority"]].concat(Object.entries(TM_PRI).map(([k, l]) => [k, l]))),
      sec("Due", "due", [["", "Any time"], ["overdue", "Overdue"], ["week", "Due within 7 days"], ["none", "No due date"]])]) } : null;
    const display = list ? { sections: [{ label: "Group by", options: [["status", "Status"], ["assignee", "Person"], ["kind", "Type"], ["priority", "Priority"]], value: f.group || "status", base: "status",
        pick: (val) => { S.tmF = { ...(S.tmF || {}), group: val }; reload(); } },
      { label: "Finished work", options: [["", "Hide"], ["1", "Show the last 12 weeks"]], value: f.done ? "1" : "", base: "", pick: (val) => { S.tmF = { ...(S.tmF || {}), done: !!val }; reload(); } }] }
      : tab === "people" ? { sections: [{ label: "Order", options: [["load", "Most open work first"], ["name", "Name"], ["done", "Most finished this week"], ["handoffs", "Most handoffs (12 weeks)"]], value: S.tmSort || "load", base: "load", pick: (val) => { S.tmSort = val; reload(); } }] } : null;
    const can = tmCanAssign();
