    const late = now.filter((x) => x.overdue), slow = now.filter((x) => !x.overdue), shownLate = late.slice(0, TM_TOP), shownSlow = slow.slice(0, Math.max(0, TM_TOP - shownLate.length));
    const more = now.length - shownLate.length - shownSlow.length;
    const workBtn = btn("Open Work", "tm-tab", { sm: true, data: { v: "work" } });        // the lists here are the top of each (the read keeps 20 of each)
    const hidden = v.comparisons_hidden ? '<p class="tmd-note">Per-person figures are hidden by the owner. Team totals are still shown.</p>' : "";
    main.innerHTML = '<div class="xp-page lx-page tm">' + strip + hidden + '<div class="tmd-grid">' +
      tmCard("Needs attention", now.length ? fmtN(t.overdue) + " overdue · " + fmtN(t.sla_breached_open) + " past their target time" : "", '<div id="tmOv"></div>', { cls: " tmd-card--list", head: workBtn }) +
      tmCard("Who has room", "Open work for each person against the limit of " + fmtN(v.wip_limit) + ".", tmLoadChart(v)) +
      tmCard("Finished each week", "The last 12 weeks, by people and by Xevrion.", tmWeeksChart(v), { cls: " tmd-card--wide" }) +
      tmCard("Time from created to done", "Typical time for each kind of work, and how long 9 in 10 took.", tmCycleChart(v), { cls: " tmd-card--wide" }) +
      "</div></div>";
    const strips = main.querySelector ? main.querySelector(".lx-strip, .xp-strip") : null;
