    ".xp .tc-row:focus-visible,.xp .tc-act:focus-visible,.xp .tc-more button:focus-visible{outline:2px solid var(--xp-purple,#5d3fe0);outline-offset:1px}",
    ".xp .tc-row b{display:block;overflow:hidden;color:var(--t1);font-weight:510;white-space:nowrap;text-overflow:ellipsis}.xp .tc-row small{display:block;overflow:hidden;color:var(--t3);font-size:12px;white-space:nowrap;text-overflow:ellipsis}",
    ".xp .tc-row[data-unread] b{font-weight:640}.xp .tc-row[data-unread] small{color:var(--t2)}",
    ".xp .tc-av--x{background:transparent;border:1px solid var(--line2)}.xp .tc-av--x svg{display:block}",
    ".xp .tc-box{display:flex;align-items:flex-end;gap:8px;padding:6px 6px 6px 12px;border:1px solid var(--line2);border-radius:var(--r-card,10px);background:#101113}.xp .tc-box:focus-within{border-color:var(--xp-purple,#5d3fe0)}",
    ".xp .tc-box textarea{flex:1;min-width:0;min-height:32px!important;max-height:180px;padding:6px 0!important;border:0!important;outline:0!important;background:transparent!important;resize:none!important;font:400 14px/20px var(--font);color:var(--t1)}",
    ".xp .tc-box-a{display:flex;gap:8px}.xp .tc-ib{display:inline-grid;place-items:center;width:32px;height:32px;border:1px solid var(--line2);border-radius:var(--r-ctl,6px);background:transparent;color:var(--t2);cursor:pointer}",
    ".xp .tc-ib:hover{border-color:var(--line3);color:var(--t1);background:rgba(255,255,255,.03)}.xp .tc-ib:focus-visible{outline:2px solid var(--xp-purple,#5d3fe0);outline-offset:2px}",
    ".xp .tc-ib.tc-send{border-color:var(--xp-purple,#5d3fe0);background:var(--xp-purple,#5d3fe0);color:#ffffff}.xp .tc-ib.tc-send:hover{filter:none;background:var(--xp-purple,#5d3fe0);border-color:#fff3}",
    ".xp .tc-help{display:block;margin-top:8px;color:var(--t3);font-size:12px}",
    ".xp .tc-av{display:inline-grid;place-items:center;width:28px;height:28px;border-radius:50%;background:#2e3036;color:#f7f8f8;font:600 11px var(--font)}.xp .tc-av[data-g]{border-radius:var(--r-ctl,6px);border:1px solid var(--line2);background:transparent;color:var(--t2)}",
    ".xp .tc-n{min-width:20px;height:20px;padding:0 8px;border-radius:10px;background:var(--xp-purple,#5d3fe0);color:#ffffff;font:600 11px/20px var(--font);text-align:center}.xp .tc-n[data-m]{background:#c9bdfb;color:#101113}",
    ".xp .tc-main{display:flex;flex-direction:column;min-width:0;min-height:0}",
