  // the drawer's parts: only the ones a page has (the console's pages give What and Next only)
  function guideStrip(id, open = false) {
    const g = guideText(id); if (!g) return "";
    const [what, why, how, nxt] = g, [next, to] = nxt || ["", ""];
    const col = (l, t) => t ? '<div class="xg-c xg-c--' + l.toLowerCase() + '"><b>' + l + "</b><p>" + esc(t) + "</p></div>" : "";
    const go = to && to !== id && pageOf(to) ? ' <button type="button" class="xg-go" data-go="' + esc(to) + '">Open ' + esc((pageOf(to) || {}).label || "") + " →</button>" : "";
    const n = [what, why, how, next].filter(Boolean).length || 1;
    return '<section class="xg-d" id="xg-d-' + esc(id) + '" style="--xg-n:' + n + '" aria-label="How this page works"' + (open ? "" : " hidden") + ">" + col("What", what) + col("Why", why) + col("How", how) +
      (next ? '<div class="xg-c xg-c--next"><b>Next</b><p>' + esc(next) + go + "</p></div>" : "") +
      '<div class="xg-f">' + btn("Turn off instructions", "guide-off", { sm: true, tone: "ghost" }) + btn("Close", "guide-toggle", { sm: true, data: { page: id } }) + "</div></section>";
  }
