    ".xp .fs3-tw{overflow-x:auto;margin:0 -4px}",
    ".xp .fs3-tbl{width:100%;border-collapse:collapse;font:400 12.5px/18px var(--font);color:var(--t2);font-variant-numeric:tabular-nums}",
