    ".xp .fs3-tbl thead th{border-top:0;font:500 12px/16px var(--font);color:var(--t3);padding-top:2px}",
    ".xp .fs3-tbl tbody th{font-weight:500;color:var(--t1);max-width:180px;overflow:hidden;text-overflow:ellipsis}",
    ".xp .fs3-tbl .n{text-align:right}.xp .fs3-q{color:var(--t4)}",
    ".xp .fs3-pane .ch{margin:0}",
    ".xp .fs-today .fs3-month ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}",
    ".xp .fs-today .fs3-month li+li{border-top:1px solid var(--line)}",
    ".xp .fs-today .fs3-month button{all:unset;box-sizing:border-box;width:100%;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:9px 0;cursor:pointer}",
    ".xp .fs-today .fs3-month button:hover b{color:var(--xp-purple-ink)}.xp .fs-today .fs3-month button:focus-visible{outline:1px solid var(--xp-purple);outline-offset:2px;border-radius:6px}",
    ".xp .fs-today .fs3-month button>span{display:flex;flex-direction:column;gap:1px;min-width:0}",
    ".xp .fs-today .fs3-month b{font:500 13px/18px var(--font);color:var(--t1)}",
