    if (!jobs.length) {
      fsFrame(main, { about, list: '<div class="fs3-state">' + lxEmpty({ title: xero ? "Record your first finished job" : "Connect Xero to start", ic: xero ? "operations" : "integrations",
        text: xero ? "Add the job, its proof and the agreed price. A person approves it before a draft invoice is made in Xero." : "Completed jobs become draft invoices in your own Xero, after a person approves each one.",
        action: xero ? fsAct("Record completed job", "fs-job", "service.operate", {}, "primary") : btn("Connect Xero", "", { go: "connections", tone: "primary", sm: true }) }) + "</div>" });
      return;
    }
    // 24B2: Invoices is the list; its figures and chart are on Overview
    const host = fsFrame(main, { about });
