    ".xp .wb-tasks li{display:grid;grid-template-columns:44px minmax(0,1fr) auto;gap:10px;align-items:center;padding:6px 0;border-top:1px solid var(--line)}",
    ".xp .wb-tasks li:first-child{border-top:0}.xp .wb-tasks li>span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--t1)}",
    ".xp .wb-tasks small{font:400 11.5px/16px var(--mono);color:var(--t3);font-variant-numeric:tabular-nums;white-space:nowrap}",
    ".xp .wb-chips{display:flex;flex-wrap:wrap;gap:6px}",
    ".xp .wb-chip{display:inline-flex;align-items:center;height:22px;padding:0 8px;border:1px solid var(--line2);border-radius:6px;font:400 11.5px/1 var(--mono);color:var(--t2)}",
    ".xp .wb-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px;max-width:880px}",
    ".xp .wb-form .wb-wide{grid-column:1/-1}",
    ".xp .wb-radio{display:flex;flex-direction:column;gap:6px;min-width:0}",
    ".xp .wb-radio>span{font:500 12px/16px var(--font);color:var(--t2)}",
    ".xp .wb-opts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}",
    ".xp .wb-opt{position:relative;display:flex;flex-direction:column;gap:2px;min-width:0;padding:10px 12px;border:1px solid var(--line2);border-radius:8px;cursor:pointer}",
    ".xp .wb-opt input{position:absolute;opacity:0;pointer-events:none}",
    ".xp .wb-opt b{font:500 13px/18px var(--font);color:var(--t1)}.xp .wb-opt small{font:400 11.5px/16px var(--font);color:var(--t3)}",
    ".xp .wb-opt:has(input:checked){border-color:#5d3fe0;background:rgba(93,63,224,.18)}",
    ".xp .wb-opt:has(input:focus-visible){outline:2px solid #8b74f5;outline-offset:2px}",
    ".xp .wb-preview{padding:12px 14px;border:1px dashed var(--line3);border-radius:8px;font:400 12.5px/18px var(--font);color:var(--t2);white-space:pre-wrap;overflow-wrap:anywhere}",
    ".xp .wb-save{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:16px}",
    ".xp .wb-save>small{font:400 12px/16px var(--font);color:var(--t3)}",
    ".xp .wb-more{display:flex;flex-wrap:wrap;gap:8px}",
    ".xp .wb-figs4 .fs3-figs{border-top:0}",
    ".xp .wb-note{margin:12px 0 0;font:400 12px/17px var(--font);color:var(--t3)}",
    ".xp .wb-views{list-style:none;margin:0;padding:0}",
    ".xp .wb-views li{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;align-items:center;padding:10px 0;border-top:1px solid var(--line)}",
    ".xp .wb-views li:first-child{border-top:0}.xp .wb-views li>div{display:flex;flex-direction:column;min-width:0}",
    ".xp .wb-views b{font:500 13px/18px var(--font);color:var(--t1);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}",
    ".xp .wb-views small{font:400 12px/16px var(--font);color:var(--t3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}",
    ".xp .wb-views li>span{display:flex;gap:8px}",
    "@media (max-width:1100px){.xp .wb-grid--3{grid-template-columns:repeat(2,minmax(0,1fr))}}",
