      form = '<fieldset class="wb-form" data-wb-form' + ro + ">" + field({ name: "default_template_id", label: "Every new project starts with", type: "select", value: s.default_template_id || "", options: opts, hint: "Its tasks are added when the project is made, starting that day." }) + "</fieldset>";
      const st = (pmView && pmView.settings) || {};
      more = btn("Planning: hours, focus and change rules", "pm-settings", { sm: true });
      form += st && Object.keys(st).length ? '<div class="wb-meta" style="margin-top:14px"><span>Change requests <b>' + esc(st.change_mode === "auto" ? "applied by themselves (undo for 30 minutes)" : "wait for you") + "</b></span><span>Week <b>" + esc(fmtN(st.hours_per_week || 37.5, 1)) + " h</b></span><span>Focus <b>" + esc(pct(st.focus_factor || 0.85)) + "</b></span></div>" : "";
