    ".xp .pm-x{all:unset;cursor:pointer;color:var(--t4);padding:2px 6px;border-radius:5px}.xp .pm-x:hover{color:var(--t1);background:var(--bg3)}.xp .pm-x:focus-visible{outline:1px solid var(--xp-purple)}",
    ".xp .pm-chart{padding:14px 24px 6px}",
