    "@media (max-width:1100px){.xp .pm-band{grid-template-columns:repeat(3,minmax(0,1fr))}.xp .pm-band>.pm-cell:nth-child(3){border-right:0}.xp .pm-band>.pm-cell:nth-child(-n+3){border-bottom:1px solid var(--line)}.xp .pm-steps{grid-template-columns:repeat(2,minmax(0,1fr))}.xp .pm-step:nth-child(2)::after{display:none}}",
    "@media (max-width:720px){.xp .pm-band{grid-template-columns:repeat(2,minmax(0,1fr))}.xp .pm-band>.pm-cell{border-bottom:1px solid var(--line);padding:10px 16px}.xp .pm-band>.pm-cell:nth-child(2n){border-right:0}.xp .pm-band>.pm-cell:nth-child(3){border-right:1px solid var(--line)}.xp .pm-band>.pm-cell:last-child{border-bottom:0;grid-column:1/-1;border-right:0}",
    ".xp .pm-tl{grid-template-columns:150px minmax(0,1fr)}.xp .pm-tl-row[data-k=t]{padding-left:22px}.xp .pm-tl-row{padding-left:10px}.xp .pm-tl-row>.lx-av,.xp .pm-tl-row>.lx-label,.xp .pm-tl-row[data-k=p]>small{display:none}",
